<?php
declare(strict_types=1);$config=require __DIR__.'/../config/database.php';$pdo=new PDO("mysql:host={$config['host']};dbname={$config['dbname']};charset={$config['charset']}",$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="hache-alumnos-horarios-'.date('Ymd').'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','w');fputcsv($out,['Alumno','Estado','Plan','Precio','Horario','WhatsApp']);$st=$pdo->query("SELECT a.nombre,a.estado_administrativo,p.nombre plan,p.precio,CONCAT(TIME_FORMAT(h.hora_inicio,'%H:%i'),'–',TIME_FORMAT(h.hora_fin,'%H:%i')) horario,a.whatsapp FROM alumnos a LEFT JOIN planes p ON p.id=a.plan_actual_id LEFT JOIN horarios h ON h.id=a.horario_preferido_id ORDER BY h.hora_inicio,a.nombre");foreach($st as $r)fputcsv($out,$r);fclose($out);